import{_ as s,o as i,c as t,a2 as a}from"./chunks/framework.BVRek7U2.js";const k=JSON.parse(`{"title":"Architecture","description":"Understand how Kyro CMS integrates seamlessly with Astro's islands architecture and prevents Node.js dependencies from bloating your client bundles.","frontmatter":{"title":"Architecture","description":"Understand how Kyro CMS integrates seamlessly with Astro's islands architecture and prevents Node.js dependencies from bloating your client bundles."},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":1785053995000}`),o={name:"architecture.md"};function n(r,e,l,c,d,h){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="architecture-export-splitting" tabindex="-1">Architecture &amp; Export Splitting <a class="header-anchor" href="#architecture-export-splitting" aria-label="Permalink to &quot;Architecture &amp; Export Splitting&quot;">​</a></h1><p>Kyro is built specifically for <strong>Astro</strong>. Unlike other CMS platforms that were originally designed for Express or Next.js and later adapted for Astro, Kyro is architected around Astro&#39;s unique constraints: Server-Side Rendering (SSR), static generation (SSG), and the Islands Architecture.</p><h2 id="the-node-js-dependency-problem" tabindex="-1">The Node.js Dependency Problem <a class="header-anchor" href="#the-node-js-dependency-problem" aria-label="Permalink to &quot;The Node.js Dependency Problem&quot;">​</a></h2><p>A common issue when integrating a Headless CMS directly into a frontend framework is &quot;dependency bleed.&quot; A CMS requires heavy Node.js libraries (database drivers like <code>pg</code> or <code>mongodb</code>, encryption libraries like <code>bcrypt</code>, caching clients like <code>redis</code>).</p><p>If your Astro components import configuration files that inadvertently import these Node.js dependencies, Vite will attempt to bundle them for the browser when hydrating your React/Vue islands, causing build crashes or massive bundle sizes.</p><h2 id="core-export-splitting" tabindex="-1">Core Export Splitting <a class="header-anchor" href="#core-export-splitting" aria-label="Permalink to &quot;Core Export Splitting&quot;">​</a></h2><p>To solve this, Kyro implements strict <strong>export splitting</strong>. We provide two distinct entrypoints that guarantee browser safety.</p><h3 id="_1-kyro-cms-core-server-only" tabindex="-1">1. <code>@kyro-cms/core</code> (Server-Only) <a class="header-anchor" href="#_1-kyro-cms-core-server-only" aria-label="Permalink to &quot;1. \`@kyro-cms/core\` (Server-Only)&quot;">​</a></h3><p>This is the primary backend entrypoint. It includes all Node.js built-ins and heavy dependencies.</p><p>You should <strong>only</strong> import from <code>@kyro-cms/core</code> in:</p><ul><li>Your <code>kyro.config.ts</code> file</li><li>API endpoint files (e.g., <code>src/pages/api/[...kyro].ts</code>)</li><li>Astro components that are strictly server-rendered (no <code>client:*</code> directives)</li></ul><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">import</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> { </span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  createKyro, </span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  createDrizzleAdapter, </span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  RedisAuthAdapter </span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">} </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">from</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &quot;@kyro-cms/core&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">;</span></span></code></pre></div><h3 id="_2-kyro-cms-core-client-browser-safe" tabindex="-1">2. <code>@kyro-cms/core/client</code> (Browser-Safe) <a class="header-anchor" href="#_2-kyro-cms-core-client-browser-safe" aria-label="Permalink to &quot;2. \`@kyro-cms/core/client\` (Browser-Safe)&quot;">​</a></h3><p>This entrypoint is guaranteed to be 100% free of Node.js dependencies. It exports TypeScript types, styling utilities, and lightweight browser helpers.</p><p>You should import from <code>@kyro-cms/core/client</code> in:</p><ul><li>React/Vue/Svelte components that use <code>client:load</code>, <code>client:idle</code>, etc.</li><li>Client-side scripts</li><li>Tailwind or styling configuration files</li></ul><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">import</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> type</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> { KyroConfig, CollectionConfig } </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">from</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &quot;@kyro-cms/core/client&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">;</span></span>
<span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">import</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> { defaultLightTheme, generateCSSVariables } </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">from</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &quot;@kyro-cms/core/client&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">;</span></span></code></pre></div><h2 id="the-single-config-philosophy" tabindex="-1">The Single Config Philosophy <a class="header-anchor" href="#the-single-config-philosophy" aria-label="Permalink to &quot;The Single Config Philosophy&quot;">​</a></h2><p>Kyro is entirely driven by a single configuration object. Instead of scattering your models across multiple folders or managing database schemas manually, you define a single <code>kyro.config.ts</code>.</p><p>From this one file, Kyro automatically generates:</p><ol><li><strong>The Database Schema</strong> (and handles migrations via Drizzle)</li><li><strong>The REST API</strong> endpoints</li><li><strong>The GraphQL Schema</strong> and resolvers</li><li><strong>The tRPC Router</strong></li><li><strong>The Admin Dashboard</strong> UI forms and tables</li><li><strong>The TypeScript Client SDK</strong></li></ol><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">import</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> { defineConfig, createLocalAdapter } </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">from</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &quot;@kyro-cms/core&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">;</span></span>
<span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">import</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> { z } </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">from</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &quot;zod&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">export</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> default</span><span style="--shiki-light:#8250DF;--shiki-dark:#D2A8FF;"> defineConfig</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">({</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  adapter: </span><span style="--shiki-light:#8250DF;--shiki-dark:#D2A8FF;">createLocalAdapter</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">({ path: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;./data.db&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> })</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">,</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  collections: [</span></span>
<span class="line"><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">    // Your entire app architecture is defined here</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  ]</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">})</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">;</span></span></code></pre></div><p>By passing this configuration to the <code>createApiHandler</code> (for your backend) and the <code>&lt;Admin /&gt;</code> component (for your frontend), the entire system stays perfectly synchronized.</p><h2 id="graphql-schema" tabindex="-1">GraphQL Schema <a class="header-anchor" href="#graphql-schema" aria-label="Permalink to &quot;GraphQL Schema&quot;">​</a></h2><p>The GraphQL schema is built statically at startup. A per-request <code>RelationLoader</code> batches relationship lookups (DataLoader pattern) to prevent N+1 queries. The schema includes Apollo Federation <code>@key</code> directives and Relay Connection types.</p><h2 id="shared-access-control" tabindex="-1">Shared Access Control <a class="header-anchor" href="#shared-access-control" aria-label="Permalink to &quot;Shared Access Control&quot;">​</a></h2><p>Access control is unified across all three protocols (REST, GraphQL, tRPC) via the shared <code>checkCollectionAccess()</code> / <code>checkGlobalAccess()</code> functions in <code>src/access/checker.ts</code>.</p><h2 id="kyro-connect-typed-sdk" tabindex="-1">kyro-connect Typed SDK <a class="header-anchor" href="#kyro-connect-typed-sdk" aria-label="Permalink to &quot;kyro-connect Typed SDK&quot;">​</a></h2><p>The kyro-connect SDK provides a fully typed client with generic <code>CollectionClient&lt;T, F&gt;</code>, <code>GqlClient</code>, and <code>UploadClient</code> classes.</p><h2 id="edge-cases-common-pitfalls" tabindex="-1">Edge Cases &amp; Common Pitfalls <a class="header-anchor" href="#edge-cases-common-pitfalls" aria-label="Permalink to &quot;Edge Cases &amp; Common Pitfalls&quot;">​</a></h2><h3 id="_1-accidentally-importing-kyro-cms-core-into-client-islands" tabindex="-1">1. Accidentally Importing <code>@kyro-cms/core</code> into Client Islands <a class="header-anchor" href="#_1-accidentally-importing-kyro-cms-core-into-client-islands" aria-label="Permalink to &quot;1. Accidentally Importing \`@kyro-cms/core\` into Client Islands&quot;">​</a></h3><ul><li><strong>The Issue:</strong> Importing <code>@kyro-cms/core</code> inside a client-side component (e.g. <code>&lt;Admin client:load /&gt;</code> or a React island) causes Vite to attempt bundling Node.js modules (<code>node:fs</code>, <code>node:crypto</code>, database drivers), resulting in build crashes.</li><li><strong>The Solution:</strong> Always import browser types, themes, and client utilities from <code>@kyro-cms/core/client</code>.</li></ul><h3 id="_2-react-hooks-errors-multiple-react-instances" tabindex="-1">2. React Hooks Errors (Multiple React Instances) <a class="header-anchor" href="#_2-react-hooks-errors-multiple-react-instances" aria-label="Permalink to &quot;2. React Hooks Errors (Multiple React Instances)&quot;">​</a></h3><ul><li><strong>The Issue:</strong> If <code>@kyro-cms/admin</code> and <code>@astrojs/react</code> resolve separate instances of <code>react</code> in node_modules, React throws <code>Invalid hook call</code> errors at runtime.</li><li><strong>The Solution:</strong> <code>@kyro-cms/astro</code> automatically deduplicates <code>react</code> and <code>react-dom</code> in Vite&#39;s <code>resolve.dedupe</code> setting.</li></ul><h3 id="_3-cjs-esm-virtual-module-interop" tabindex="-1">3. CJS / ESM Virtual Module Interop <a class="header-anchor" href="#_3-cjs-esm-virtual-module-interop" aria-label="Permalink to &quot;3. CJS / ESM Virtual Module Interop&quot;">​</a></h3><ul><li><strong>The Issue:</strong> When bundling SSR routes in Astro, virtual modules (like <code>\\0debug-browser</code>) imported via CJS <code>require()</code> can wrap exports as <code>{ default: debug }</code> instead of a callable function.</li><li><strong>The Solution:</strong> Kyro virtual shims export <code>module.exports = debug; debug.default = debug;</code> for dual CJS/ESM interop compatibility.</li></ul><h3 id="_4-empty-string-form-normalization" tabindex="-1">4. Empty String Form Normalization <a class="header-anchor" href="#_4-empty-string-form-normalization" aria-label="Permalink to &quot;4. Empty String Form Normalization&quot;">​</a></h3><ul><li><strong>The Issue:</strong> HTML text inputs return empty strings <code>&quot;&quot;</code> for untouched fields, which can break relational foreign keys or non-string database fields.</li><li><strong>The Solution:</strong> Kyro automatically normalizes empty strings <code>&quot;&quot;</code> to <code>null</code> for non-textual fields prior to database operations.</li></ul>`,38)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
